  Jh = `若有提供焦點橫幅圖片，您的活動或公告可以顯示於您的遊戲的 Steam 收藏庫遊戲詳情頁面的「開始遊戲」按鈕下方。`,
  Yh = `收藏庫：位於您的遊戲在玩家 Steam 收藏庫中的頁面`,
