  Zh = `取決於擁有您的遊戲、能在自己的 Steam 收藏庫中看見您的遊戲的玩家人數。`,
  Qh = `工作坊頁面`,
  $h = `您可以在您的遊戲的 Steam 工作坊中張貼此活動或公告。若希望啟用這項功能，請前往「選項」分頁並點選「同時張貼至工作坊」。預設狀況下，遊戲活動或公告不會出現在工作坊區塊中。`,
  eg = `特賣 Steam 產品頁面橫幅`,
  tg = `%1$s 到 %2$s 可見的產品頁面橫幅`,
  ng = `您可在「特賣」分頁中提供一張特賣橫幅，如此參與的遊戲便可在其 Steam 產品頁面頂端展示所提供的橫幅，並藉此返回特賣。這能幫助從願望清單電子郵件或商店瀏覽而發現特定遊戲折扣的顧客同時了解整個特賣活動。這些橫幅可見的期限為您活動開始至結束的時間，或為期兩週，以較早的時間為準。活動的開始及結束時間可於「選項」分頁中指定。`,
