  og = `新聞：玩家的個人化活動行事曆`,
  sg = `此活動將於收藏庫或願望清單中擁有您的遊戲，或是關注您遊戲的玩家的個人化新聞中心中顯示。`,
  cg = `通知：發送給選擇接收的玩家的手機通知`,
