  ug = `收到電子郵件的玩家`,
  dg = `包含此活動在內的預估電子郵件數量。我們會定期為每位顧客製作目標活動匯總。每位顧客選擇接收哪些電子郵件和他們的通訊偏好設定。`,
  fg = `收到行銷訊息的玩家`,
