  Gx = `這張圖片通常包含代表活動的圖像素材與品牌元素，加上任何您希望傳達的簡短訊息。部份情況下，Steam 會自動在旁邊加上您的遊戲名稱和標誌，但由於在社群媒體分享您的活動時會使用此圖片，您可能會想將遊戲標誌加入封面圖片以及此圖片內。`,
  Kx = `宣傳圖會顯示在您商店頁面中的近期公告、活動與公告列表，以及您的收藏庫詳情頁面。當活動被分享在社群媒體上時，此圖也會成為活動的代表圖片。這會成為活動或公告的連結，也可能出現於多項遊戲內容旁邊，因此圖片應清楚明瞭、易於辨認。`,
  qx = `此圖像通常包含代表您發行商、開發者或系列作的圖像素材和品牌元素。在某些情況下，Steam 將自動在此圖像旁包含您的個人圖示。`,
